(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12 + Math.cos((x-y)*0.009-t*0.2)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.03+t*0.35)*6;
  const w2y = Math.cos(sy*0.022+t*0.38)*8 + Math.sin(sx*0.028-t*0.42)*6;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.2, 1.0],
    [340+Math.cos(t*0.45)*100, 150+Math.sin(t*0.6)*55, 0.09, 1.8, 0.85],
    [240+Math.sin(t*0.28+2)*130, 100+Math.cos(t*0.42+1)*80, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*55, 0.11, 1.4, 0.9],
    [380+Math.sin(t*0.38+4)*80, 50+Math.cos(t*0.8+2)*65, 0.065, 2.8, 0.95],
    [200+Math.cos(t*0.32+5)*110, 210+Math.sin(t*0.48)*70, 0.085, 2.0, 1.05],
    [300+Math.sin(t*0.6+3)*70, 120+Math.cos(t*0.5+4)*60, 0.1, 1.6, 0.8],
    [80+Math.cos(t*0.55+2)*60, 100+Math.sin(t*0.65+1)*80, 0.07, 2.4, 1.15]
  ];
  let aS=0, iS=0, wSum=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((px-sX)**2 + (py-sY)**2);
    aS += Math.sin(d*f - t*sp)*w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.8)*w;
    wSum += w;
  }
  const act=aS/wSum, inh=iS/wSum;
  const bg1 = (Math.sin(px*0.035+py*0.022+t*0.7)+Math.sin(px*0.028-py*0.038+t*0.95))/2;
  const bg2 = Math.sin((px+py)*0.11+t*2.2)*0.25 + Math.sin((px-py)*0.095-t*1.8)*0.25;
  const bg3 = Math.sin(px*0.06+py*0.04+t*1.5)*0.15 + Math.cos(px*0.05-py*0.07-t*1.2)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((px-cx)**2+(py-cy)**2), ang=Math.atan2(py-cy,px-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const nx = px*0.08, ny = py*0.08;
  const cell = Math.sin(nx)*Math.sin(ny)+Math.sin(nx*1.5+ny*0.7+t*0.8)*0.4+Math.sin(nx*0.6-ny*1.3+t*0.6)*0.3;
  const voronoi = (() => {
