      md = Math.min(md, Math.sqrt((px-ppx)**2+(py-ppy)**2));
    }
    return Math.sin(md*0.15-t*1.5)*0.4;
  })();
  const laplacian = (() => {
    const s = 3;
    const v00 = Math.sin((px)*0.15)*Math.sin((py)*0.15);
