  })();
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + cell*0.2 + voronoi + laplacian*0.15)*2.0);
  const membrane = Math.tanh((Math.abs(reaction)-0.35)*8)*0.3;
