    [5,12,52],[10,35,78],[12,62,95],[18,95,105],[28,135,120],[65,165,115],
    [140,190,100],[195,195,85],[220,170,75],[210,130,65],[185,90,70],[155,60,72],
    [110,38,68],[65,22,60],[30,15,55],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const edge = Math.abs(reaction)>0.6?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*edge*pulse + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*edge*pulse + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*edge*pulse + glow*90)|0)
  ];
}
